const chapters={
 clitoralcomplex:{title:'Clitoral erectile complex',latin:'Clitoris · corpora cavernosa et bulbi vestibuli',system:'female',region:'Anterior perineum; deep to vulvar surface and along ischiopubic rami',size:'Variable · visible glans is only a small external portion',blood:'Internal pudendal → deep and dorsal clitoral arteries; posterior labial branches',nerve:'Dorsal nerve of clitoris (pudendal S2–S4); cavernous autonomic fibers via pelvic plexus',photo:'clitoral-complex.jpg',blurb:'A three-dimensional neurovascular and erectile complex: paired crura, body, glans and closely related vestibular bulbs.',summary:'The visible glans is not the whole clitoris. Two corpora cavernosa join into a body, while proximal crura anchor to the ischiopubic rami. The glans is particularly sensory and is not simply another corpus cavernosum. Paired vestibular bulbs are neighboring erectile tissue flanking the vestibule, anatomically distinguished from the corpora. Arterial inflow, smooth-muscle relaxation and venous outflow restriction contribute to engorgement; somatic sensation travels largely in the dorsal clitoral nerve.',
 entries:[
 ['Clitoral glans','Glans clitoridis','Sensory','External distal part beneath or exposed by the hood; dense sensory innervation and distinct histology from cavernous bodies.','Conveys fine sensation.','Do not describe the glans as a paired cavernous body.'],
 ['Clitoral prepuce','Preputium clitoridis','Surface','Fold of skin derived from the anterior labia minora covering part of the glans.','Protects and permits mobility of glans.','Its form and degree of coverage vary normally.'],
 ['Clitoral body','Corpus clitoridis','Erectile','Midline body formed by apposition of the paired corpora cavernosa, deep to the external glans.','Engorges via cavernous vascular spaces.','The externally visible part understates total size.'],
 ['Right corpus cavernosum','Corpus cavernosum dextrum','Erectile','One of the paired erectile cylinders of the clitoral body, enclosed by tunica albuginea.','Fills with blood during arousal.','Separate it anatomically from the vestibular bulb.'],
 ['Left corpus cavernosum','Corpus cavernosum sinistrum','Erectile','Contralateral cavernous cylinder joining the body along the midline.','Contributes to body rigidity and expansion.','Paired anatomy can be traced into the crura.'],
 ['Crura of clitoris','Crura clitoridis','Attachment','Two proximal cavernous limbs fixed to the inferior pubic and ischial rami.','Anchor the erectile body to pelvic bone.','Deep crura cannot be assessed from surface appearance alone.'],
 ['Vestibular bulbs','Bulbi vestibuli','Erectile','Paired spongy masses on either side of vaginal and urethral vestibule, superficial to perineal membrane.','Engorge and narrow the vaginal opening during arousal.','These are related but distinct from clitoral corpora cavernosa.'],
 ['Tunica albuginea','Tunica albuginea','Fascia','Fibrous coat around the paired corpora cavernosa.','Contains expansion of cavernous spaces.','Not the same thin investing tissue as the glans.'],
 ['Ischiocavernosus','Musculus ischiocavernosus','Muscle','Paired superficial perineal muscles covering each clitoral crus.','Compress crura and assist venous outflow restriction.','Pudendal motor innervation via perineal branches.'],
 ['Bulbospongiosus','Musculus bulbospongiosus','Muscle','Paired muscles around the vestibular bulbs and vaginal opening.','Compresses vestibular bulbs and helps narrow introitus.','Distinct from deep pelvic-floor levator ani.'],
 ['Suspensory ligament','Ligamentum suspensorium clitoridis','Support','Fibrous connection from pubic symphysis to clitoral body.','Suspends and stabilizes the body.','A surgical landmark near the dorsal neurovascular bundle.'],
 ['Dorsal clitoral nerve','Nervus dorsalis clitoridis','Somatic nerve','Terminal sensory branch of pudendal nerve running dorsolaterally toward body and glans.','Carries much of clitoral touch sensation.','Potentially vulnerable in anterior perineal procedures.'],
 ['Cavernous autonomic fibers','Nervi cavernosi','Autonomic','Pelvic plexus fibers reaching erectile tissue through perineal neurovascular pathways.','Regulate vascular smooth muscle and engorgement.','Not interchangeable with pudendal somatic sensory fibers.'],
 ['Deep clitoral artery','Arteria profunda clitoridis','Artery','Internal pudendal terminal branch entering each cavernosal crus.','Supplies cavernous erectile tissue.','Pelvic arterial branching varies between individuals.'],
 ['Dorsal clitoral artery','Arteria dorsalis clitoridis','Artery','Internal pudendal branch coursing along dorsal body toward glans.','Supplies dorsal complex and glans.','Runs near dorsal nerve; avoid assuming identical paths in every person.'],
 ['Venous drainage','Venae clitoridis','Vein','Superficial and deep venous channels drain to pudendal/pelvic veins.','Permits normal detumescence.','Engorgement reflects inflow together with reduced venous outflow.'] ],
 hot:{cruraofclitoris:[290,360],vestibularbulbs:[365,635],clitoralbody:[500,420],dorsalclitoralnerve:[350,340],deepclitoralartery:[400,420],bulbospongiosus:[470,800]},
 cards:[['Three-dimensional map','Glans + hood are external landmarks; body, paired crura and vestibular bulbs are mostly internal. The bulbs flank the vestibule rather than forming the paired clitoral cavernosa.'],['Neural distinction','Dorsal clitoral nerve is a sensory pudendal branch; cavernous autonomic pathways modulate erectile smooth muscle. Do not equate sensation with vasomotor control.'],['Clinical safety','The dorsal neurovascular bundle and bulb/crural relationships matter in perineal surgery. Illustrations simplify variable vessel paths.']],sources:['https://www.ncbi.nlm.nih.gov/books/NBK547703/','https://pubmed.ncbi.nlm.nih.gov/16145367/'],related:['gynvulva','gynvagina','femalepelvis','penileerectile']},
 penileerectile:{title:'Penile erectile tissue',latin:'Corpora cavernosa · corpus spongiosum',system:'male',region:'Root, shaft and glans of penis; superficial perineal pouch to external genitalia',size:'Variable · three principal longitudinal erectile columns',blood:'Internal pudendal → deep, dorsal and bulbourethral/urethral arteries',nerve:'Dorsal penile nerve (pudendal S2–S4); cavernous nerves from pelvic plexus',photo:'penile-erectile.jpg',blurb:'Two dorsal cavernous bodies and one ventral spongiosum carry arterial, neural and urethral pathways through the penis.',summary:'The paired corpora cavernosa are enveloped by strong tunica albuginea and form the main rigid erectile compartment; the ventral corpus spongiosum surrounds the penile urethra and expands distally as the glans. Deep penile arteries feed cavernous spaces. Parasympathetic-associated cavernous neural signaling relaxes smooth muscle, increasing arterial inflow and restricting subtunical venous outflow. The spongiosum remains comparatively compliant to protect urethral patency.',
 entries:[
 ['Paired corpora cavernosa','Corpora cavernosa penis','Erectile','Two dorsal longitudinal erectile cylinders that unite in shaft and separate proximally as crura.','Primary rigid erectile compartment.','Fibrous tunica helps compress emissary venous outflow.'],
 ['Corpus spongiosum','Corpus spongiosum penis','Erectile','Single ventral erectile column surrounding spongy urethra.','Engorges without compressing urethral lumen closed.','Its distal expansion is the glans penis.'],
 ['Tunica albuginea','Tunica albuginea corporum cavernosorum','Fascia','Strong fibrous sheath encasing cavernosa, with distinct collagen layers.','Resists expansion and aids venous occlusion.','Disruption during trauma can constitute penile fracture.'],
 ['Cavernosal trabeculae','Trabeculae corporum cavernosorum','Microanatomy','Smooth-muscle and connective-tissue struts bordering interconnected blood sinusoids.','Relaxation permits filling of cavernous lacunae.','Vascular dysfunction can impair rigidity.'],
 ['Deep penile arteries','Arteriae profundae penis','Artery','Internal pudendal branches traveling within each corpus cavernosum.','Feed cavernosal tissue.','Not the same as superficial dorsal arteries.'],
 ['Helicine arteries','Arteriae helicinae','Arteriole','Small coiled branches entering cavernous sinusoidal spaces.','Dilate as smooth muscle relaxes, increasing inflow.','Reduced dilation is one vascular cause of erectile dysfunction.'],
 ['Subtunical venules','Venulae subtunicales','Venous','Venules under the tunica draining cavernous lacunae.','Their compression limits venous outflow during erection.','Veno-occlusive dysfunction prevents maintained rigidity.'],
 ['Deep dorsal vein','Vena dorsalis profunda penis','Vein','Midline dorsal venous channel deep to Buck fascia between dorsal arteries.','Drains glans and erectile compartments to pelvic plexuses.','Lies in dorsal neurovascular bundle, not within the urethra.'],
 ['Dorsal arteries','Arteriae dorsales penis','Artery','Paired internal pudendal branches near dorsal vein and nerves.','Supply glans and penile coverings.','Different course from deep cavernosal arteries.'],
 ['Dorsal nerves','Nervi dorsales penis','Somatic nerve','Pudendal sensory branches along dorsal shaft.','Carry cutaneous and glanular sensation.','Motor/vascular autonomic cavernous fibers have a different route.'],
 ['Cavernous nerves','Nervi cavernosi penis','Autonomic','Pelvic plexus fibers traveling toward erectile smooth muscle.','Mediate vasodilation and erection.','Can be injured in pelvic/prostate surgery.'],
 ['Buck fascia','Fascia penis profunda','Fascia','Deep investing fascia around erectile bodies and dorsal neurovascular bundle.','Provides a deep connective-tissue envelope.','Compare with superficial Dartos fascia.'],
 ['Dartos fascia','Fascia penis superficialis','Fascia','Superficial membranous layer containing smooth muscle beneath penile skin.','Allows skin mobility and continuity with superficial perineal fascia.','Fluid can track through connected superficial fascial planes.'],
 ['Spongy urethra','Urethra spongiosa','Urinary','Penile segment of urethra coursing within corpus spongiosum.','Conveys urine and semen at different times.','Urethral injury can accompany trauma.'],
 ['Glans penis','Glans penis','Distal','Distal expansion of corpus spongiosum over tips of corpora cavernosa.','Contains terminal urethral opening and sensory receptors.','Distinct from the cavernous bodies beneath.'],
 ['Penile crura and bulb','Crura et bulbus penis','Root','Cavernous crura attach to ischiopubic rami; proximal spongiosum forms bulb in perineum.','Anchor penile root and receive inflow.','Ischiocavernosus covers crura; bulbospongiosus surrounds bulb.'] ],
 hot:{pairedcorporacavernosa:[298,400],corpusspongiosum:[295,760],tunicaalbuginea:[175,430],deepenilearteries:[258,430],deepdorsalvein:[318,280],buckfascia:[435,290],spongyurethra:[290,770]},
 cards:[['Cross-section rule','Two dorsal cavernosa with thick tunica; one ventral spongiosum wraps the urethra. Root crura and bulb connect these shaft structures to the perineum.'],['Hemodynamic sequence','Cavernous autonomic activation → arteriolar and trabecular relaxation → sinusoidal filling → subtunical venous compression. Detumescence reverses this balance.'],['Layer order','Skin → superficial Dartos fascia → deep Buck fascia → tunica albuginea → erectile trabeculae. The dorsal neurovascular bundle lies in the plane deep to Buck fascia.']],sources:['https://www.ncbi.nlm.nih.gov/books/NBK513278/','https://www.ncbi.nlm.nih.gov/books/NBK563292/'],related:['male','maleprostate','malepelvis','clitoralcomplex']},
 skinlayers:{title:'Skin layers & appendages',latin:'Epidermis · dermis · tela subcutanea',system:'integumentary',region:'Whole-body integument; thick glabrous skin of palms/soles differs from thin hairy skin',size:'Epidermal thickness varies by site; hypodermis is subcutaneous tissue, not a dermal layer',blood:'Dermal superficial and deep vascular plexuses; epidermis is avascular',nerve:'Cutaneous sensory afferents and sympathetic sudomotor/vasomotor fibers',photo:'skin-layers-deep.jpg',blurb:'The five thick-skin epidermal strata, two dermal zones, hypodermis, receptors and follicle–gland units.',summary:'Epidermis is a stratified keratinizing epithelium nourished by diffusion from vascular dermis. From deep to superficial: basale, spinosum, granulosum, optional lucidum (most evident in thick skin), and corneum. Basement membrane joins epidermis to papillary dermis; reticular dermis provides strength. The hypodermis is adipose-rich subcutis beneath the dermis. Hair, sebaceous glands and most sweat glands are skin appendages; cutaneous receptors relay varied forms of mechanical and thermal input.',
 entries:[
 ['Stratum basale','Stratum basale','Epidermis','Deep single proliferative keratinocyte layer adjoining basement membrane.','Renews overlying epidermis.','Basal-cell carcinoma derives from basal-type cells.'],
 ['Stratum spinosum','Stratum spinosum','Epidermis','Several layers of keratinocytes strongly joined by desmosomes.','Provides mechanical cohesion.','Desmosomal disruption causes epidermal blistering.'],
 ['Stratum granulosum','Stratum granulosum','Epidermis','Flattened keratinocytes with keratohyalin granules and lipid-releasing lamellar bodies.','Builds the water-permeability barrier.','Barrier injury increases transepidermal water loss.'],
 ['Stratum lucidum','Stratum lucidum','Thick skin','Thin translucent transition zone most apparent in glabrous palms and soles.','Adds specialized layer in thick skin.','Do not expect a distinct lucidum in ordinary thin hairy skin.'],
 ['Stratum corneum','Stratum corneum','Epidermis','Anucleate flattened corneocytes surrounded by intercellular lipid lamellae.','Principal external permeability barrier.','Loss in large burns causes fluid and heat loss.'],
 ['Basement membrane zone','Junctio dermoepidermalis','Interface','Anchoring complex joining epidermis to dermis with hemidesmosomes and matrix.','Resists separation and supports renewal.','Plane of separation distinguishes blister disorders.'],
 ['Dermal papillae','Papillae dermis','Interface','Fingerlike papillary dermal projections interlocking with epidermal ridges.','Increase attachment surface and house capillary loops.','Rete ridge pattern varies by body site.'],
 ['Papillary dermis','Stratum papillare dermis','Dermis','Superficial loose connective tissue with capillaries and fine collagen.','Nourishes avascular epidermis by diffusion.','Superficial wounds may preserve deep appendages.'],
 ['Reticular dermis','Stratum reticulare dermis','Dermis','Deeper dense irregular collagen-and-elastin connective tissue.','Provides tensile strength and elasticity.','Full-thickness injury through reticular dermis commonly scars.'],
 ['Hypodermis','Tela subcutanea','Subcutis','Adipose lobules and connective septa deep to the dermis.','Insulation, cushioning and movable attachment.','Not one of the histologic dermal layers.'],
 ['Melanocytes','Melanocyti','Cell','Neural-crest-derived pigment cells mainly in basal epidermis.','Transfer melanosomes to keratinocytes for UV protection.','Melanoma originates from melanocytes.'],
 ['Langerhans cells','Cellulae dendriticae epidermales','Immune','Antigen-presenting dendritic cells mainly in suprabasal epidermis.','Support immune surveillance.','Inflammatory responses involve epidermal immune cells.'],
 ['Hair follicle','Folliculus pili','Appendage','Epidermal downgrowth containing bulb, matrix and hair shaft.','Grows hair; joins pilosebaceous unit.','Glabrous palms and soles lack hair follicles.'],
 ['Sebaceous gland','Glandula sebacea','Appendage','Holocrine gland usually opening into a hair follicle.','Secretes sebum onto hair and skin.','Follicular blockage/inflammation contributes to acne.'],
 ['Eccrine sweat gland','Glandula sudorifera eccrina','Appendage','Coiled secretory gland in deep dermis with duct to skin surface.','Evaporation cools the body.','Sympathetic cholinergic fibers drive most thermoregulatory sweating.'],
 ['Apocrine sweat gland','Glandula sudorifera apocrina','Appendage','Large gland associated with follicles in axilla and selected regions.','Produces viscous secretion, especially after puberty.','Not the principal sweat gland for whole-body cooling.'],
 ['Meissner corpuscle','Corpusculum tactus','Receptor','Encapsulated rapidly adapting receptor in dermal papillae of glabrous skin.','Detects light touch and low-frequency motion.','Contributes to fingertip tactile discrimination.'],
 ['Pacinian corpuscle','Corpusculum lamellosum','Receptor','Deep onion-like lamellar receptor in dermis/subcutis.','Detects vibration and deep pressure change.','Vibratory sense can be tested clinically.'],
 ['Free nerve endings','Terminationes nervorum liberae','Receptor','Unencapsulated terminals extending into superficial skin.','Carry pain, temperature and itch signals.','Small-fiber neuropathy may impair these modalities.'] ],
 hot:{stratumcorneum:[180,190],stratumbasale:[200,320],dermalpapillae:[225,385],papillarydermis:[230,440],reticulardermis:[225,600],hypodermis:[235,850],hairfollicle:[524,500],sebaceousgland:[560,425],eccrinesweatgland:[320,630],paciniancorpuscle:[773,675]},
 cards:[['Deep → superficial','Basale → spinosum → granulosum → (lucidum in thick skin) → corneum. Below the epidermis: basement membrane → papillary dermis → reticular dermis → hypodermis.'],['Thick vs thin','Palm and sole have conspicuous lucidum and thick corneum, but no hair or sebaceous glands. Most other skin is thin and often hair-bearing.'],['Vessels and nerves','Epidermis contains sensory fibers but no vessels; dermal capillaries support it. Meissner is superficial, Pacinian is deeper; eccrine glands cool by evaporation.']],sources:['https://www.ncbi.nlm.nih.gov/books/NBK470464/','https://www.ncbi.nlm.nih.gov/books/NBK482237/'],related:['skin','facialnerve','eyeanatomy']},
 facialnerve:{title:'Facial nerve · CN VII',latin:'Nervus facialis',system:'nervous',region:'Pons → internal acoustic meatus → facial canal → stylomastoid foramen → parotid plexus',size:'Mixed cranial nerve; five conventional terminal motor branch groups',blood:'AICA/labyrinthine and petrosal branches intracranially; stylomastoid artery distally',nerve:'CN VII motor, parasympathetic and taste fibers; cutaneous face sensation mainly CN V',photo:'facial-nerve-deep.jpg',blurb:'Track facial motor branches, taste, lacrimation and salivation through the temporal bone and parotid gland.',summary:'CN VII contains motor fibers to muscles of facial expression, taste from anterior two-thirds of tongue (via chorda tympani), and parasympathetic pathways for lacrimal, submandibular and sublingual glands. It enters the internal acoustic meatus, bends at geniculate ganglion, traverses the facial canal and exits at stylomastoid foramen. Within the parotid it forms a motor plexus giving temporal, zygomatic, buccal, marginal mandibular and cervical branches; it passes through the gland but does not provide its secretomotor supply.',
 entries:[
 ['Facial motor nucleus','Nucleus nervi facialis','Brainstem','Motor cell bodies in pons send axons looping around abducens nucleus before exit.','Controls muscles of facial expression.','Upper face often retains bilateral cortical input in supranuclear lesions.'],
 ['Nervus intermedius','Nervus intermedius','Mixed','Sensory and parasympathetic root accompanying the motor root.','Carries taste and secretomotor pathways.','Explains why CN VII is not solely motor.'],
 ['Internal acoustic meatus','Meatus acusticus internus','Passage','Temporal-bone canal shared by CN VII, CN VIII and labyrinthine artery.','Conveys nerve toward facial canal.','Lesions here may affect facial movement and hearing/balance.'],
 ['Geniculate ganglion','Ganglion geniculi','Ganglion','Sensory ganglion at first sharp bend of facial canal; greater petrosal branch arises nearby.','Houses sensory neuron cell bodies.','Herpes zoster may affect geniculate region.'],
 ['Greater petrosal nerve','Nervus petrosus major','Parasympathetic','Carries preganglionic fibers toward pterygopalatine ganglion.','Supports lacrimal and nasal/palatine gland secretion.','A lesion proximal to branch can impair lacrimation.'],
 ['Nerve to stapedius','Nervus stapedius','Motor','Branch in facial canal to stapedius muscle of middle ear.','Dampens stapes movement.','Proximal lesion can produce hyperacusis.'],
 ['Chorda tympani','Chorda tympani','Taste + parasympathetic','Crosses middle ear then joins lingual nerve (V3).','Taste from anterior two-thirds of tongue; submandibular ganglion secretomotor input.','Can be injured by middle-ear disease or surgery.'],
 ['Stylomastoid foramen','Foramen stylomastoideum','Exit','Exit of CN VII from temporal bone behind ear.','Delivers motor trunk to face and neck.','Distal lesions spare proximal taste/lacrimal branches.'],
 ['Posterior auricular branch','Nervus auricularis posterior','Motor','Early extracranial branch to auricular muscles and occipitalis.','Moves posterior auricle and posterior scalp.','Arises before parotid plexus.'],
 ['Parotid plexus','Plexus intraparotideus','Motor plexus','Branching motor network within parotid gland.','Distributes facial expression motor fibers.','Parotid secretion is mainly CN IX parasympathetic, not CN VII.'],
 ['Temporal branch','Rami temporales','Motor','Superior terminal branches to frontalis and superior orbicularis oculi.','Raises brow and closes upper eyelid.','Forehead weakness helps localize lower motor neuron injury.'],
 ['Zygomatic branch','Rami zygomatici','Motor','Branches across zygomatic region to orbicularis oculi and neighboring muscles.','Closes eye and coordinates upper facial expression.','Corneal blink efferent limb is CN VII; afferent is V1.'],
 ['Buccal branch','Rami buccales','Motor','Motor branches to buccinator, orbicularis oris and upper lip muscles.','Helps seal lips and move cheek.','Not the buccal sensory nerve of mandibular CN V3.'],
 ['Marginal mandibular branch','Ramus marginalis mandibulae','Motor','Branch along mandibular margin to depressors of lower lip/chin.','Shapes lower-lip expressions.','At risk during submandibular or mandibular surgery.'],
 ['Cervical branch','Ramus colli','Motor','Inferior branch descending to platysma.','Tenses superficial neck skin.','Deep facial sensation remains principally trigeminal.'],
 ['Facial sensation · CN V','Nervus trigeminus','Contrast','V1/V2/V3 provide most cutaneous sensory input from face, unlike VII expression branches.','Separates sensory testing from facial movement testing.','Do not diagnose trigeminal sensory loss from a VII motor lesion alone.'] ],
 hot:{stylomastoidforamen:[280,380],parotidplexus:[390,465],temporalbranch:[470,170],zygomaticbranch:[510,360],buccalbranch:[610,545],marginalmandibularbranch:[610,735],cervicalbranch:[380,815]},
 cards:[['In the temporal bone','Internal acoustic meatus → geniculate ganglion → greater petrosal → stapedius branch → chorda tympani → stylomastoid exit. Branch order helps localize lesions.'],['Five motor groups','Temporal, zygomatic, buccal, marginal mandibular, cervical. These are expression motor branches, not V1/V2/V3 facial skin sensory territories.'],['Clinically compare','Peripheral VII lesion weakens ipsilateral upper and lower face; central lesions often spare brow relative to lower face, but patterns depend on lesion site. Corneal reflex: V1 in, VII out.']],sources:['https://www.ncbi.nlm.nih.gov/books/NBK554569/','https://teachmeanatomy.info/head/cranial-nerves/facial-nerve/'],related:['cranialnerves','trigeminalnerve','eyeanatomy','ear']},
 trigeminalnerve:{title:'Trigeminal nerve · CN V',latin:'Nervus trigeminus',system:'nervous',region:'Pons → trigeminal ganglion → orbit, midface and mandible',size:'Three major divisions: V1 ophthalmic, V2 maxillary, V3 mandibular',blood:'Brainstem branches and regional meningeal/orbital arterial branches',nerve:'Main somatic sensory supply of face; V3 also innervates muscles of mastication',photo:'trigeminal-deep.jpg',blurb:'Map facial sensation and masticatory motor fibers without confusing trigeminal CN V with facial CN VII.',summary:'Most facial skin sensation travels by CN V. Ophthalmic V1 supplies forehead and cornea; maxillary V2 supplies the cheek, upper lip and upper teeth; mandibular V3 supplies lower jaw, lower teeth and general anterior tongue sensation and carries motor fibers to mastication muscles. Taste from anterior tongue is carried by facial chorda tympani joining lingual V3, not by trigeminal sensory neurons. Corneal reflex enters by V1 and blink exits by VII.',
 entries:[
 ['Trigeminal sensory root','Radix sensoria nervi trigemini','Root','Large sensory root emerges from lateral pons into trigeminal cistern.','Conveys facial somatic sensation centrally.','Brainstem lesions can combine facial and body sensory findings.'],
 ['Trigeminal ganglion','Ganglion trigeminale','Ganglion','Sensory neuron cell bodies in Meckel cave; divides into V1, V2 and V3.','First-order facial sensory neurons.','Classic site involved in trigeminal neuralgia pathways.'],
 ['Ophthalmic V1','Nervus ophthalmicus','Sensory','Passes superior orbital fissure into orbit; gives frontal, lacrimal and nasociliary branches.','Sensation from forehead, upper lid and cornea.','Afferent limb of corneal reflex.'],
 ['Frontal nerve','Nervus frontalis','V1 branch','Superior orbital branch dividing into supraorbital and supratrochlear nerves.','Sensation over forehead and anterior scalp.','Forehead sensory loss suggests V1 pathway involvement.'],
 ['Nasociliary nerve','Nervus nasociliaris','V1 branch','Orbital V1 branch giving long ciliary, ethmoidal and infratrochlear fibers.','Carries corneal sensation through long ciliary nerves.','Corneal anesthesia predisposes to epithelial injury.'],
 ['Maxillary V2','Nervus maxillaris','Sensory','Leaves cranial cavity via foramen rotundum to pterygopalatine fossa.','Sensation to midface, upper teeth and palate.','V2 neuralgia pain may localize to cheek or upper jaw.'],
 ['Infraorbital nerve','Nervus infraorbitalis','V2 branch','Continuance of V2 through infraorbital canal to face.','Sensation to lower lid, side of nose and upper lip.','Infraorbital fracture may cause cheek numbness.'],
 ['Superior alveolar nerves','Nervi alveolares superiores','V2 branch','Dental branches entering maxillary alveolar region.','General sensation from upper teeth.','Important in maxillary dental anesthesia.'],
 ['Mandibular V3','Nervus mandibularis','Mixed','Sensory and motor roots unite at foramen ovale.','Sensation lower face and motor to mastication.','Only trigeminal division carrying branchial motor fibers.'],
 ['Auriculotemporal nerve','Nervus auriculotemporalis','V3 branch','Runs near temporomandibular joint and parotid; conveys postganglionic fibers from otic ganglion.','Sensory temple/ear and carrier for parotid secretomotor fibers.','The secretomotor origin is CN IX via otic ganglion.'],
 ['Buccal sensory nerve','Nervus buccalis','V3 branch','Long buccal branch carrying sensation from cheek mucosa and skin.','Cheek general sensation.','Not the buccal motor branch of facial CN VII.'],
 ['Lingual nerve','Nervus lingualis','V3 branch','Supplies general sensation to anterior tongue; joined by VII chorda tympani.','Touch/pain anterior tongue; carries taste fibers belonging to VII.','At risk in third-molar surgery.'],
 ['Inferior alveolar nerve','Nervus alveolaris inferior','V3 branch','Enters mandibular foramen and canal to lower teeth, ending as mental nerve.','Lower tooth and chin sensation.','Mental numbness may follow mandibular injury.'],
 ['Mental nerve','Nervus mentalis','V3 branch','Terminal branch exits mental foramen.','Sensation to chin and lower lip.','Mental foramen position matters for dental procedures.'],
 ['Motor root of V3','Radix motoria trigemini','Motor','Pons motor fibers bypass sensory ganglion then travel with V3.','Controls masseter, temporalis, pterygoids and several small muscles.','Jaw deviates toward a weak side when opened.'],
 ['Corneal reflex loop','Reflexus cornealis','Reflex','Corneal touch → nasociliary V1 → brainstem → bilateral facial VII efferents.','Protective blink.','Test sensory afferent and eyelid motor efferent separately.'] ],
 hot:{trigeminalganglion:[465,335],ophthalmicv1:[660,215],maxillaryv2:[690,465],mandibularv3:[635,585],infraorbitalnerve:[770,490],inferioralveolarnerve:[650,680]},
 cards:[['Three exits','V1 → superior orbital fissure; V2 → foramen rotundum; V3 → foramen ovale. V3 is the mixed division.'],['Avoid branch-name trap','Buccal nerve (V3) gives sensation; buccal branch of facial VII drives expression muscles. Lingual V3 carries general tongue sensation but joined chorda tympani taste fibers belong to VII.'],['Corneal protection','V1 nasociliary/long ciliary afferent; bilateral VII orbicularis oculi efferent. Different deficits can abolish the same blink.']],sources:['https://www.ncbi.nlm.nih.gov/books/NBK482283/','https://teachmeanatomy.info/head/cranial-nerves/trigeminal-nerve/'],related:['cranialnerves','facialnerve','eyeanatomy']},
 eyeanatomy:{title:'Eye · microscopic layers',latin:'Bulbus oculi · tunicae oculi',system:'sensory',region:'Orbit; anterior refractive media to posterior neural retina and optic nerve',size:'Adult axial length ≈ 24 mm, with normal variation',blood:'Ophthalmic artery: central retinal and posterior ciliary branches; aqueous is avascular',nerve:'II vision; III/IV/VI eye movement; V1 corneal sensation; III parasympathetic pupil/contraction',photo:'eye-layers-deep.jpg',blurb:'Three ocular coats, five classical corneal layers, aqueous route, lens suspension, macula and optic disc.',summary:'The globe has an outer fibrous tunic (cornea and sclera), vascular uvea (iris, ciliary body and choroid) and inner neural tunic (retina). Aqueous from ciliary processes flows posterior chamber → pupil → anterior chamber → trabecular meshwork/Schlemm canal or uveoscleral routes. Corneal epithelium, Bowman layer, stroma, Descemet membrane and endothelium are the classical five-layer teaching scheme; some texts describe an additional pre-Descemet layer. Retina transforms light to neural signals; the optic disc lacks photoreceptors.',
 entries:[
 ['Corneal epithelium','Epithelium anterius corneae','Cornea','Surface stratified nonkeratinizing epithelial layer.','Barrier and smooth refractive surface.','Abrasion causes pain because the cornea is richly innervated.'],
 ['Bowman layer','Lamina limitans anterior','Cornea','Acellular anterior limiting layer beneath epithelium.','Adds anterior structural support.','Damage may scar rather than regenerate as normal layer.'],
 ['Corneal stroma','Substantia propria corneae','Cornea','Organized collagen lamellae form most of corneal thickness.','Precise collagen arrangement maintains transparency.','Edema disrupts transparency.'],
 ['Descemet membrane','Lamina limitans posterior','Cornea','Basement membrane of corneal endothelium.','Supports endothelial monolayer.','Can develop folds with corneal edema.'],
 ['Corneal endothelium','Endothelium posterius corneae','Cornea','Single posterior cell layer lining anterior chamber.','Pumps fluid from stroma to maintain optical clarity.','Cell loss may cause persistent edema.'],
 ['Sclera','Sclera','Fibrous coat','Opaque collagenous external coat continuous with cornea at limbus.','Protects and preserves globe contour.','Extraocular muscles insert into sclera.'],
 ['Iris and pupil','Iris et pupilla','Uvea','Pigmented iris surrounds adjustable central pupil.','Controls light entry via sphincter and dilator pupillae.','Direct/consensual light reflex requires II afferent and III efferent.'],
 ['Ciliary body','Corpus ciliare','Uvea','Ring with ciliary processes and muscle between iris and choroid.','Makes aqueous and adjusts zonular tension for accommodation.','Ciliary processes produce aqueous.'],
 ['Zonular fibers','Fibrae zonulares','Suspensory','Fine ligaments linking ciliary processes to lens equator.','Transmit tension to crystalline lens.','Disruption permits lens subluxation.'],
 ['Crystalline lens','Lens crystallina','Refractive','Transparent avascular biconvex structure in capsule behind iris.','Changes shape to fine-tune focus.','Opacity is cataract.'],
 ['Posterior chamber','Camera posterior bulbi','Aqueous','Narrow aqueous space behind iris and before lens/zonules.','Receives newly secreted aqueous.','Not the large vitreous chamber.'],
 ['Anterior chamber','Camera anterior bulbi','Aqueous','Space between corneal endothelium and anterior iris/lens plane.','Conducts aqueous to drainage angle.','Angle configuration influences glaucoma risk.'],
 ['Trabecular meshwork','Reticulum trabeculare','Outflow','Porous tissue at iridocorneal angle leading to Schlemm canal.','Main conventional aqueous drainage pathway.','Outflow resistance raises intraocular pressure.'],
 ['Canal of Schlemm','Sinus venosus sclerae','Outflow','Circumferential channel draining trabecular aqueous to episcleral veins.','Returns aqueous to venous circulation.','Not a blood vessel supplying the retina.'],
 ['Choroid','Choroidea','Uvea','Pigmented vascular layer between retina and sclera.','Supplies outer retina, especially photoreceptors.','Choroidal disease can damage central vision.'],
 ['Neural retina','Retina neurosensorialis','Neural coat','Layered light-processing tissue with rods, cones, interneurons and ganglion cells.','Converts light into optic-nerve signals.','Detached neurosensory retina loses support from RPE.'],
 ['Macula and fovea','Macula lutea et fovea centralis','Retina','Posterior central retinal specialization with densely packed foveal cones.','High-acuity central vision.','Macular disease disrupts reading and fine detail.'],
 ['Optic disc','Discus nervi optici','Exit','Site where retinal ganglion axons and central retinal vessels exit/enter.','Forms optic nerve and retinal vascular entry.','No photoreceptors: physiological blind spot.'],
 ['Vitreous body','Corpus vitreum','Gel','Transparent gel behind lens occupying the vitreous chamber.','Supports globe and transmits light.','Vitreous traction can produce floaters or retinal tears.'] ],
 hot:{cornealepithelium:[230,460],sclera:[400,175],irisandpupil:[294,487],ciliarybody:[317,360],crystallinelens:[362,476],anteriorchamber:[262,455],choroid:[690,270],neuralretina:[700,300],maculaandfovea:[655,540],opticdisc:[713,496],vitreousbody:[530,475]},
 cards:[['Three tunics','Fibrous: cornea + sclera. Vascular/uveal: iris + ciliary body + choroid. Neural: retina plus retinal pigment epithelium interface.'],['Five classical corneal layers','Epithelium → Bowman layer → stroma → Descemet membrane → endothelium. A newer pre-Descemet description is used in some sources, so layer counts vary by convention.'],['Aqueous vs vitreous','Aqueous: ciliary processes → posterior chamber → pupil → anterior chamber → trabecular/uveoscleral outflow. Vitreous occupies the large chamber behind the lens.']],sources:['https://www.ncbi.nlm.nih.gov/books/NBK544343/','https://www.merckmanuals.com/home/eye-disorders/biology-of-the-eyes/structure-and-function-of-the-eyes'],related:['eye','retina','facialnerve','trigeminalnerve']},
 retina:{title:'Retina · neural microanatomy',latin:'Retina neurosensorialis · epithelium pigmentosum',system:'sensory',region:'Inner posterior globe; photoreceptors interface with pigment epithelium and choroid',size:'Ten classical histologic retinal layers including retinal pigment epithelium',blood:'Inner retina: central retinal artery; outer retina: choriocapillaris',nerve:'Ganglion cell axons → optic nerve II; autonomic supply regulates ocular vessels',photo:'retina-deep.jpg',blurb:'Rods, cones, bipolar and ganglion circuits; fovea, optic disc, pigment epithelium and dual blood supply.',summary:'Light traverses inner retinal layers before reaching rods and cones against retinal pigment epithelium (RPE). Neural signaling runs the opposite direction: photoreceptors → bipolar cells → ganglion cells → optic nerve. Horizontal and amacrine cells modify lateral signaling. The foveal center has dense cones and displaced inner layers for acuity, while the optic disc has no photoreceptors. Inner retina is supported mainly by central retinal circulation; photoreceptors and RPE depend strongly on the choriocapillaris.',
 entries:[
 ['Internal limiting membrane','Membrana limitans interna','Layer 1','Müller-cell endfeet make retinal inner boundary against vitreous.','Supports vitreoretinal interface.','Epiretinal traction can distort macula.'],
 ['Nerve fiber layer','Stratum neurofibrarum','Layer 2','Unmyelinated ganglion axons converge toward optic disc.','Conducts output to optic nerve.','Glaucoma thins nerve fiber layer.'],
 ['Ganglion cell layer','Stratum ganglionare','Layer 3','Retinal ganglion somata whose axons become optic nerve.','Final retinal output neurons.','Ganglion-cell loss contributes to glaucomatous vision loss.'],
 ['Inner plexiform layer','Stratum plexiforme internum','Layer 4','Synapses among bipolar, amacrine and ganglion processes.','Processes contrast and temporal information.','Layer distortion can accompany retinal edema.'],
 ['Inner nuclear layer','Stratum nucleare internum','Layer 5','Bipolar, horizontal, amacrine and Müller cell bodies.','Relays and modulates photoreceptor signals.','Microvascular ischemia affects inner retinal circuitry.'],
 ['Outer plexiform layer','Stratum plexiforme externum','Layer 6','Photoreceptor terminals synapse with bipolar and horizontal cells.','First central synaptic relay for light signals.','Fluid at this level can disturb signal transfer.'],
 ['Outer nuclear layer','Stratum nucleare externum','Layer 7','Nuclei of rods and cones.','Supports photoreceptor cell population.','Thinning indicates photoreceptor loss.'],
 ['External limiting membrane','Membrana limitans externa','Layer 8','Adherens junction belt between Müller cells and photoreceptors.','Provides organized retinal scaffold.','Continuity is assessed in retinal imaging.'],
 ['Photoreceptor segments','Stratum bacillorum et conorum','Layer 9','Rod and cone inner/outer segments facing RPE.','Capture photons and start phototransduction.','Outer-segment injury impairs vision despite intact inner retina.'],
 ['Retinal pigment epithelium','Epithelium pigmentosum retinae','Layer 10','Pigmented monolayer adjacent to photoreceptors and Bruch membrane.','Recycles visual pigment, phagocytoses shed discs and forms outer blood–retinal barrier.','Separation from neurosensory retina is a retinal detachment plane.'],
 ['Rods','Bacilli','Photoreceptor','Highly light-sensitive photoreceptors predominating away from foveal center.','Dim-light and peripheral vision.','Rod loss impairs night vision.'],
 ['Cones','Coni','Photoreceptor','Color- and acuity-sensitive photoreceptors concentrated at fovea.','High-resolution daylight and color vision.','Cone dysfunction reduces central/color vision.'],
 ['Müller glia','Cellulae Müller','Glia','Radial support cells spanning retinal layers.','Maintain homeostasis, structure and metabolic support.','Their endfeet contribute to limiting membranes.'],
 ['Fovea centralis','Fovea centralis','Macula','Small central pit with closely spaced cones and displaced inner layers.','Peak spatial acuity.','Foveal injury causes major central visual impairment.'],
 ['Optic disc','Discus nervi optici','Exit','Ganglion axons and central retinal vessels pass through; no rods or cones.','Forms physiological blind spot.','Disc swelling can reflect raised intracranial pressure.'],
 ['Central retinal artery','Arteria centralis retinae','Vessel','Ophthalmic branch entering optic nerve and supplying inner retinal layers.','Perfuses much of inner retina.','Occlusion can cause acute monocular visual loss.'],
 ['Choriocapillaris','Lamina choriocapillaris','Vessel','Dense vascular bed of choroid external to Bruch membrane.','Supplies outer retina and RPE by diffusion.','Choroidal circulation is crucial for photoreceptor viability.'],
 ['Bruch membrane','Lamina vitrea choroideae','Interface','Multilayered extracellular sheet between RPE and choriocapillaris.','Supports nutrient exchange.','Age-related changes are associated with macular disease.'] ],
 hot:{foveacentralis:[600,275],photoreceptorsegments:[620,610],retinalpigmentepithelium:[620,685],choriocapillaris:[620,755],bruchmembrane:[620,715],ganglioncelllayer:[170,375]},
 cards:[['Ten layers, inside → out','Internal limiting → nerve fiber → ganglion → inner plexiform → inner nuclear → outer plexiform → outer nuclear → external limiting → photoreceptor segments → retinal pigment epithelium.'],['Signal direction','Light enters from vitreous side toward outer photoreceptors; neural messages return inward through bipolar to ganglion cells, then optic nerve.'],['Two vascular territories','Central retinal branches nourish inner retina; choriocapillaris sustains RPE and outer photoreceptors. Foveal central zone minimizes overlying vessels/inner layers.']],sources:['https://www.ncbi.nlm.nih.gov/books/NBK544343/','https://www.ncbi.nlm.nih.gov/books/NBK546692/'],related:['eyeanatomy','eye','trigeminalnerve']}
};
Object.assign(chapters,{
 nephron:{title:'Nephron · kidney microanatomy',latin:'Nephron · corpusculum renale',system:'urinary',region:'Renal cortex (corpuscle and convoluted tubules) → medulla (loop and collecting system)',size:'Microscopic functional unit; cortical and juxtamedullary nephrons differ in loop depth',blood:'Afferent arteriole → glomerulus → efferent arteriole → peritubular capillaries/vasa recta',nerve:'Renal sympathetic fibers reach vasculature, juxtaglomerular cells and tubules',photo:'nephron-deep.jpg',blurb:'Follow filtration through glomerular barrier, segmented tubules, medullary loop and collecting ducts.',summary:'Each nephron begins with a glomerular capillary tuft inside Bowman capsule; the filtration barrier includes fenestrated endothelium, glomerular basement membrane and podocyte slit diaphragms. Filtrate enters proximal tubule, descends and ascends in the loop of Henle, then passes distal tubule into a collecting duct. Collecting ducts arise from a different embryologic lineage than nephron tubules. Peritubular capillaries and vasa recta reclaim water and solutes; juxtaglomerular apparatus links distal salt sensing to renin secretion.',entries:[
 ['Afferent arteriole','Arteriola afferens','Vessel','Brings arterial blood into glomerular capillary tuft.','Regulates incoming glomerular pressure.','Diameter influences filtration rate.'],
 ['Glomerular capillaries','Glomerulus','Filtration','Fenestrated capillary loops between afferent and efferent arterioles.','Pass plasma water and small solutes toward Bowman space.','Damage may permit albumin or red cells into urine.'],
 ['Efferent arteriole','Arteriola efferens','Vessel','Vessel leaves glomerulus and feeds downstream capillary network.','Maintains filtration pressure and supplies cortical/medullary beds.','Unique arteriole between two capillary beds.'],
 ['Bowman capsule','Capsula glomeruli','Corpuscle','Parietal squamous layer and visceral podocyte layer enclosing Bowman space.','Collects primary filtrate from glomerulus.','Filtrate flows from urinary pole to proximal tubule.'],
 ['Filtration basement membrane','Membrana basalis glomerularis','Barrier','Specialized basement membrane shared by capillary endothelium and podocytes.','Contributes size/charge selectivity.','Thickening or injury can alter permeability.'],
 ['Podocyte foot processes','Pedicelli podocytorum','Barrier','Interdigitating podocyte extensions with slit diaphragms over glomerular capillaries.','Final cellular component of filtration barrier.','Effacement accompanies proteinuric disease.'],
 ['Mesangial cells','Cellulae mesangiales','Support','Cells and matrix between capillary loops inside glomerulus.','Support capillaries, clear debris and modulate surface area.','Mesangial proliferation appears in several glomerular diseases.'],
 ['Proximal convoluted tubule','Tubulus contortus proximalis','Tubule','Cortical segment with cuboidal cells and dense apical brush border.','Reabsorbs most filtered water, sodium, glucose and amino acids.','Proximal injury can produce generalized solute loss.'],
 ['Thin descending limb','Crus descendens tenue','Loop','Thin segment descending toward renal medulla.','Highly water-permeable component of countercurrent system.','Water exits toward hypertonic medulla.'],
 ['Ascending limb','Crus ascendens ansae nephroni','Loop','Thin and thick ascending segments climb from medulla; thick limb actively transports salt.','Dilutes luminal fluid and helps establish medullary gradient.','Thick ascending limb is relatively water-impermeable.'],
 ['Vasa recta','Vasa recta renis','Vessel','Straight medullary capillaries especially from juxtamedullary efferent arterioles.','Countercurrent exchange preserves medullary gradient.','Medullary hypoperfusion can injure deep segments.'],
 ['Distal convoluted tubule','Tubulus contortus distalis','Tubule','Cortical segment downstream of loop, including specialized macula densa region.','Fine-tunes electrolyte handling.','Thiazides target distal NaCl transporter.'],
 ['Macula densa','Macula densa','Sensor','Distal tubular epithelial plaque where tubule contacts its own vascular pole.','Senses tubular salt and mediates tubuloglomerular feedback.','Part of juxtaglomerular apparatus.'],
 ['Juxtaglomerular cells','Cellulae juxtaglomerulares','Hormonal','Modified smooth-muscle cells of afferent arteriole near vascular pole.','Secrete renin in response to regulatory signals.','Renin initiates renin–angiotensin–aldosterone cascade.'],
 ['Collecting duct','Ductus colligens','Outflow','Receives distal connecting tubules from multiple nephrons and descends through medulla.','ADH-sensitive water reabsorption and acid/base regulation.','Embryologically distinct from nephron proper.'],
 ['Principal cells','Cellulae principales','Collecting duct','Collecting duct epithelial cells controlling sodium and water channels.','Respond to aldosterone and vasopressin/ADH.','ADH resistance impairs urine concentration.'],
 ['Intercalated cells','Cellulae intercalatae','Collecting duct','Acid/base-specialized collecting duct cells with subtype-dependent transport.','Secrete hydrogen or bicarbonate as appropriate.','Tubular acidification defects can cause acidosis.'],
 ['Papillary duct','Ductus papillaris','Outflow','Terminal medullary collecting channel opening at renal papilla into minor calyx.','Delivers final urine to calyces.','Obstruction downstream backs urine toward collecting system.'] ],hot:{afferentarteriole:[300,270],glomerularcapillaries:[360,275],bowmancapsule:[375,300],proximalconvolutedtubule:[455,220],thindescendinglimb:[500,580],ascendinglimb:[575,555],vasarecta:[482,730],distalconvolutedtubule:[640,220],collectingduct:[695,510],papillaryduct:[655,895]},cards:[['Blood vs filtrate','Blood: afferent arteriole → glomerular capillaries → efferent arteriole → peritubular capillaries/vasa recta. Filtrate: Bowman space → proximal → loop → distal → collecting duct.'],['Where the barrier lives','Fenestrated glomerular endothelium + glomerular basement membrane + podocyte filtration slits. Bowman parietal layer encloses the space but is not the slit diaphragm.'],['Juxtaglomerular feedback','Macula densa at distal tubule senses luminal NaCl; juxtaglomerular granular cells near the afferent arteriole release renin.']],sources:['https://www.ncbi.nlm.nih.gov/books/NBK549766/','https://www.ncbi.nlm.nih.gov/books/NBK57113/'],related:['kidney','bladder','vascular']},
 brachialplexus:{title:'Brachial plexus · arm nerves',latin:'Plexus brachialis',system:'nervous',region:'C5–T1 ventral rami between scalene muscles → behind clavicle → axilla and upper limb',size:'5 roots · 3 trunks · 6 divisions · 3 cords · 5 major terminal nerves',blood:'Cords surround axillary artery; regional supply from subclavian/axillary branches',nerve:'Ventral rami C5–T1, with frequent prefixed/postfixed variation',photo:'brachial-plexus-deep.jpg',blurb:'Trace the arm nerve network from spinal roots through trunks, divisions and cords to five terminal nerves.',summary:'The brachial plexus usually arises from ventral rami C5–T1. C5–6 form upper trunk, C7 middle trunk and C8–T1 lower trunk. Each trunk divides anteriorly and posteriorly; anterior divisions of upper/middle form lateral cord, lower forms medial cord, all posterior divisions form posterior cord. Cords are named relative to the axillary artery. Musculocutaneous, axillary, radial, median and ulnar nerves reach the limb; several important scapular and pectoral branches leave the plexus before these endpoints.',entries:[
 ['C5–T1 ventral rami','Rami anteriores C5–T1','Roots','Five spinal nerve ventral rami build the typical plexus; not the intrathecal dorsal/ventral rootlets.','Provide segmental motor and sensory fibers to upper limb.','Anatomy can be prefixed C4–C8 or postfixed C6–T2.'],
 ['Interscalene passage','Spatium interscalenum','Route','Roots and trunks pass between anterior and middle scalene muscles.','Conveys plexus out of neck.','Site of interscalene regional anesthesia.'],
 ['Upper trunk','Truncus superior','Trunk','Formed by union of C5 and C6 ventral rami.','Redistributes upper-root fibers into divisions.','Upper-trunk traction can weaken shoulder abduction and elbow flexion.'],
 ['Middle trunk','Truncus medius','Trunk','Continuation of C7 ventral ramus.','Feeds anterior and posterior divisions.','C7 contribution enters multiple terminal nerves.'],
 ['Lower trunk','Truncus inferior','Trunk','Formed by C8 and T1 ventral rami.','Carries lower-root fibers toward hand pathways.','Lower-trunk damage may weaken intrinsic hand muscles.'],
 ['Anterior divisions','Divisiones anteriores','Division','One anterior division from each trunk, usually destined for limb flexor compartments.','Create lateral and medial cords.','Divisions lie posterior to clavicle.'],
 ['Posterior divisions','Divisiones posteriores','Division','One posterior division from each trunk converges on posterior cord.','Feed extensor-compartment pathways.','Differentiate divisions from posterior spinal nerve rami.'],
 ['Lateral cord','Fasciculus lateralis','Cord','Upper and middle trunk anterior divisions join lateral to axillary artery.','Gives musculocutaneous and lateral root of median nerve.','Named relative to axillary artery.'],
 ['Medial cord','Fasciculus medialis','Cord','Continuation of lower trunk anterior division, medial to axillary artery.','Gives ulnar and medial root of median nerve.','Medial cutaneous nerves of arm/forearm also arise here.'],
 ['Posterior cord','Fasciculus posterior','Cord','All three posterior divisions unite posterior to axillary artery.','Gives axillary and radial nerves.','Vulnerable in axillary trauma.'],
 ['Musculocutaneous nerve','Nervus musculocutaneus','Terminal','Lateral-cord branch through coracobrachialis to arm flexors.','Elbow flexion and lateral forearm sensation.','Injury weakens biceps/brachialis and lateral forearm sensation.'],
 ['Median nerve','Nervus medianus','Terminal','Receives lateral and medial cord roots in axilla; travels through forearm to hand.','Most forearm flexors, thenar muscles, lateral palmar digits.','Compression at carpal tunnel affects median sensory territory.'],
 ['Ulnar nerve','Nervus ulnaris','Terminal','Medial-cord continuation descends behind medial humeral epicondyle.','Most intrinsic hand muscles and medial hand sensation.','Vulnerable at elbow/cubital tunnel.'],
 ['Axillary nerve','Nervus axillaris','Terminal','Posterior-cord branch through quadrangular space around surgical neck of humerus.','Deltoid, teres minor and lateral shoulder skin.','Shoulder dislocation can injure it.'],
 ['Radial nerve','Nervus radialis','Terminal','Large posterior-cord branch courses through radial groove and forearm.','Extensors of elbow, wrist and fingers; posterior limb sensation.','Radial groove injury may cause wrist drop.'],
 ['Long thoracic nerve','Nervus thoracicus longus','Root branch','C5–C7 root-level branch descending along serratus anterior.','Holds scapula against chest wall.','Damage can cause medial scapular winging.'],
 ['Suprascapular nerve','Nervus suprascapularis','Trunk branch','Upper-trunk branch to supraspinatus and infraspinatus.','Starts shoulder abduction and external rotation.','Can be trapped near suprascapular notch.'],
 ['Axillary artery','Arteria axillaris','Landmark','Artery in axilla around which plexus cords are named.','Provides spatial reference, not a neural component.','Cord labels are meaningless without artery orientation.'] ],hot:{c5t1ventralrami:[375,200],interscalenepassage:[380,290],uppertrunk:[450,310],middletrunk:[460,360],lowertrunk:[480,400],anteriordivisions:[575,390],lateralcord:[640,465],posteriorcord:[620,520],axillaryartery:[670,575]},cards:[['Five → three → six → three → five','Five roots (C5–T1) → upper/middle/lower trunks → anterior and posterior divisions of each trunk → lateral/posterior/medial cords → five principal terminal nerves.'],['Cord derivation','Upper + middle anterior divisions → lateral cord. Lower anterior → medial cord. All three posterior divisions → posterior cord. Cords named by position relative to axillary artery.'],['Clinical map','Upper trunk: shoulder/elbow deficit; lower trunk: hand weakness; posterior cord: radial/axillary pattern. Injury patterns overlap; examination and electrodiagnostics refine localization.']],sources:['https://www.ncbi.nlm.nih.gov/books/NBK531473/','https://www.ncbi.nlm.nih.gov/books/NBK538136/'],related:['nervous','spinalcord','muscle','shoulder','facialnerve']}
});

